CREATE VIEW 'energy_ledger' AS ( 
SELECT ts, book, symbol, curve, qty, settle_px AS px, 'sod' AS src
                FROM energy_position_snapshots
                UNION ALL
                SELECT ts, book, symbol, curve, qty, px, 'trade' AS src
                FROM energy_fills
);

